-- # Lernfeld 5: Cyberphysische Systeme > ## Datengrundlagen > - Datenarten

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können qualitative Daten allein durch numerische Werte ausgedrückt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Qualitative Daten beschreiben Eigenschaften, nicht nur Zahlen"}, {"text": "Ja", "correct": false, "because": "Numerische Kodierung verliert Nuancen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diskrete Daten immer das Ergebnis einer Messung mit festen Intervallen?', 2, '[{"text": "Nein", "correct": true, "because": "Diskrete Daten sind abgegrenzte Werte, nicht nur Messungen"}, {"text": "Ja", "correct": false, "because": "Zählwerte sind auch diskret"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, dass kontinuierliche Daten durch eine endliche Anzahl von Messpunkten vollständig repräsentiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierliche Daten haben unendlich viele Werte"}, {"text": "Ja", "correct": false, "because": "Näherung ist keine vollständige Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können strukturierte Daten gleichzeitig als unstrukturierte Daten betrachtet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur schließt Unstrukturiertheit aus"}, {"text": "Ja", "correct": false, "because": "Definitionen widersprechen sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind kategorische Daten immer ordinal, wenn sie in einer Rangfolge angeordnet werden können?', 2, '[{"text": "Nein", "correct": true, "because": "Kategorisch kann nominal ohne Rangfolge sein"}, {"text": "Ja", "correct": false, "because": "Nominaldaten haben keine natürliche Ordnung"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Datenart beschreibt eine Temperaturmessung mit beliebigen Dezimalwerten am besten?', 2, '[{"text": "Kontinuierlich", "correct": true, "because": "Unendlich viele Zwischenwerte möglich"}, {"text": "Diskret", "correct": false, "because": "Diskret hat feste Schritte"}, {"text": "Nominal", "correct": false, "because": "Nominal beschreibt Kategorien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenart repräsentiert eine Aufzählung von Farben ohne Rangfolge?', 3, '[{"text": "Nominal", "correct": true, "because": "Kategorien ohne Ordnung"}, {"text": "Ordinal", "correct": false, "because": "Ordnung fehlt"}, {"text": "Quantitativ", "correct": false, "because": "Keine numerische Messung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was charakterisiert halbstrukturierte Daten im Gegensatz zu strukturierten Daten?', 2, '[{"text": "Flexibilität in der Organisation", "correct": true, "because": "Tags statt fester Schemata"}, {"text": "Fehlende Metadaten", "correct": false, "because": "Metadaten sind oft vorhanden"}, {"text": "Numerische Präzision", "correct": false, "because": "Nicht auf Zahlen beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenart würde eine Zählung der Besucher pro Stunde in einem Museum repräsentieren?', 2, '[{"text": "Diskret", "correct": true, "because": "Ganze Zahlen ohne Zwischenwerte"}, {"text": "Kontinuierlich", "correct": false, "because": "Keine Gleitkommawerte"}, {"text": "Qualitativ", "correct": false, "because": "Numerisch, nicht beschreibend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenart beschreibt eine Rangliste von Wettbewerbsteilnehmern mit ungleichen Abständen?', 2, '[{"text": "Ordinal", "correct": true, "because": "Rangfolge ohne metrische Abstände"}, {"text": "Intervall", "correct": false, "because": "Gleiche Abstände fehlen"}, {"text": "Nominal", "correct": false, "because": "Rangfolge vorhanden"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Datenarten gehören zur Gruppe der quantitativen Daten?', 4, '[{"text": "Diskret", "correct": true, "because": "Numerisch und zählbar"}, {"text": "Kontinuierlich", "correct": true, "because": "Numerisch und messbar"}, {"text": "Nominal", "correct": false, "because": "Kategorisch, nicht numerisch"}, {"text": "Ordinal", "correct": false, "because": "Rangfolge, nicht metrisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften treffen auf unstrukturierte Daten zu?', 3, '[{"text": "Kein festes Schema", "correct": true, "because": "Frei formatiert"}, {"text": "Schwer maschinenlesbar", "correct": true, "because": "Fehlende Struktur erschwert Analyse"}, {"text": "Immer numerisch", "correct": false, "because": "Kann Text oder Bilder sein"}, {"text": "Hohe Verarbeitungskapazität nötig", "correct": true, "because": "Komplexität der Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele repräsentieren qualitative Daten?', 3, '[{"text": "Kundenzufriedenheit: Gut", "correct": true, "because": "Beschreibend, nicht numerisch"}, {"text": "Gewicht: 5,2 kg", "correct": false, "because": "Numerisch, quantitativ"}, {"text": "Farbe: Blau", "correct": true, "because": "Kategorisch"}, {"text": "Temperatur: 23,5°C", "correct": false, "because": "Numerisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenarten können eine Rangfolge aufweisen?', 4, '[{"text": "Ordinal", "correct": true, "because": "Definiert durch Rangfolge"}, {"text": "Intervall", "correct": true, "because": "Numerisch mit Ordnung"}, {"text": "Nominal", "correct": false, "because": "Keine natürliche Ordnung"}, {"text": "Verhältnis", "correct": true, "because": "Numerisch mit Rangfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale unterscheiden halbstrukturierte Daten von anderen Datenarten?', 3, '[{"text": "Verwendung von Tags", "correct": true, "because": "Flexibles Schema"}, {"text": "Feste Tabellenstruktur", "correct": false, "because": "Typisch für strukturierte Daten"}, {"text": "Selbstbeschreibend", "correct": true, "because": "Metadaten enthalten"}, {"text": "Nur binäre Formate", "correct": false, "because": "Nicht auf Binär beschränkt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kontinuierliche Daten können durch diskrete Werte exakt dargestellt werden. b) Qualitative Daten sind immer subjektiv.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Kontinuierlich unendlich, Qualitative nicht immer subjektiv"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nominaldaten können eine natürliche Ordnung haben. b) Halbstrukturierte Daten sind vollständig maschinenlesbar.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Nominal ohne Ordnung, Halbstrukturiert nicht immer lesbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Diskrete Daten können Gleitkommawerte enthalten. b) Strukturierte Daten erfordern ein festes Schema.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Diskret nur ganzzahlig, Struktur braucht Schema"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Qualitative Daten können in ordinalen Skalen organisiert werden. b) Kontinuierliche Daten sind immer intervallskaliert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualitativ kann ordinal sein, Kontinuierlich nicht nur Intervall"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unstrukturierte Daten sind für relationale Datenbanken optimiert. b) Verhältnisdaten haben einen absoluten Nullpunkt.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Unstrukturiert nicht für RDBMS, Verhältnis hat Nullpunkt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

